import React, { useState } from "react";

export default function SafetyCheck({ tourist }) {
  const [location, setLocation] = useState(null);
  const [status, setStatus] = useState("");

  const handleCheckSafety = () => {
    if (!navigator.geolocation) {
      alert("Geolocation is not supported by your browser.");
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        const { latitude, longitude } = pos.coords;
        setLocation({ latitude, longitude });
        setStatus(
          `Location fetched successfully! (Lat: ${latitude.toFixed(3)}, Lng: ${longitude.toFixed(3)})`
        );
      },
      () => {
        setStatus("Unable to retrieve your location.");
      }
    );
  };

  return (
    <div style={rootStyle}>
      <div style={cardStyle}>
        {/* 👇 Personalized greeting */}
        <h2 style={{ color: "#ff6f00", marginBottom: "20px" }}>
          Welcome, {tourist?.name || "Traveler"} 🌏
        </h2>

        <p style={{ color: "#6b4d2b" }}>
          Your Block ID: <strong>{tourist?.blockId}</strong>
        </p>

        <p style={{ color: "#6b4d2b", marginTop: "10px" }}>
          Click below to fetch your location and check safety around you.
        </p>

        <button onClick={handleCheckSafety} style={buttonStyle}>
          Fetch My Location & Check Safety
        </button>

        {status && (
          <p style={{ marginTop: "15px", color: "#3b1f04" }}>
            {status}
          </p>
        )}

        {location && (
          <div style={mapPlaceholder}>
            <p>
              📍 Latitude: {location.latitude.toFixed(4)} <br />
              📍 Longitude: {location.longitude.toFixed(4)}
            </p>
            <p style={{ fontStyle: "italic" }}>
              (Future feature: live route & safety alerts!)
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

const rootStyle = {
  minHeight: "100vh",
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  background:
    "linear-gradient(135deg, rgba(255,156,66,0.9), rgba(255,111,0,0.85)), url('https://images.unsplash.com/photo-1541417904950-b855846fe074?auto=format&fit=crop&w=1500&q=80')",
  backgroundSize: "cover",
  backgroundPosition: "center",
  fontFamily: "'Poppins', sans-serif",
};

const cardStyle = {
  background: "rgba(255,255,255,0.9)",
  padding: "30px 35px",
  borderRadius: 20,
  boxShadow: "0 12px 40px rgba(0,0,0,0.25)",
  textAlign: "center",
  width: 420,
  maxWidth: "90%",
};

const buttonStyle = {
  background: "#ff6f00",
  color: "white",
  border: "none",
  padding: "12px 16px",
  borderRadius: 10,
  cursor: "pointer",
  fontWeight: 600,
  marginTop: "15px",
};

const mapPlaceholder = {
  background: "rgba(255,255,255,0.8)",
  marginTop: "20px",
  borderRadius: 12,
  padding: "15px",
  boxShadow: "0 4px 10px rgba(0,0,0,0.1)",
};
